CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Fused maxpool + hardtanh kernel.
// Grid: (N*C, ceil(H_out/TH), ceil(W_out/TW))
// Each thread computes one output element: max over pool_k x pool_k window, then clamp.
#define TILE_H 16
#define TILE_W 16

__global__ void fused_pool_hardtanh_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int pool_k, int pool_stride,
    int H_out, int W_out,
    float ht_min, float ht_max
) {
    // Shared memory tile: (TILE_H*pool_stride + pool_k - 1) x (TILE_W*pool_stride + pool_k - 1)
    // For pool_k=2, stride=2: (32+1) x (32+1) = 33x33 = 1089 floats
    // Pad row width by 1 to avoid bank conflicts
    const int SMEM_H = TILE_H * 2 + 1;  // covers pool_stride=2, pool_k=2
    const int SMEM_W = TILE_W * 2 + 1;
    const int SMEM_ROW = SMEM_W + 1;    // +1 padding to avoid bank conflicts
    __shared__ float smem[33 * 34];     // SMEM_H=33, SMEM_ROW=34

    int nc = blockIdx.x;
    if (nc >= N * C) return;
    int n = nc / C;
    int c = nc % C;

